import React, { useEffect, useState } from "react";
import {
  View, Text, StyleSheet, TextInput, TouchableOpacity,
  ScrollView, Alert, SafeAreaView, KeyboardAvoidingView,
  Platform, StatusBar, ActivityIndicator
} from "react-native";
import axios from "axios";
import { useRouter } from "expo-router";
import { Feather } from "@expo/vector-icons";
import AsyncStorage from "@react-native-async-storage/async-storage";

const COLORS = {
  dark: "#0a3d2e",
  accent: "#1f6f54",
  silver: "#94a3b8",
  bg: "#fcfdfd",
  border: "#f1f5f9",
  white: "#ffffff"
};

export default function Perfil() {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [cargandoDatos, setCargandoDatos] = useState(true);
  
  const [usuario, setUsuario] = useState({
    id_usuario: null,
    nombre_completo: "",
    correo: "",
    celular: "",
    direccion: ""
  });

  const [passwordData, setPasswordData] = useState({
    password_actual: "", 
    password: ""
  });

  useEffect(() => {
    cargarDatos();
  }, []);

  const cargarDatos = async () => {
    try {
      const usuarioRaw = await AsyncStorage.getItem("usuario");
      if (!usuarioRaw) return router.replace("/login");
      
      const user = JSON.parse(usuarioRaw);
      const res = await axios.get(`http://192.168.1.9:3000/api/usuarios/${user.id_usuario}`);
      
      setUsuario(res.data);
    } catch (error) {
      console.error("Error al cargar:", error);
    } finally {
      setCargandoDatos(false);
    }
  };

  const guardarCambios = async () => {
    // 1. Verificación de ID antes del await
    if (!usuario.id_usuario) {
      return Alert.alert("Error", "ID de usuario no encontrado.");
    }

    try {
      setLoading(true);
      
      // 2. Limpieza de datos para evitar el 400
      const payload = {
        correo: usuario.correo.trim(),
        celular: String(usuario.celular).trim(),
        direccion: usuario.direccion ? usuario.direccion.trim() : ""
      };

      console.log("📡 INICIANDO PUT A:", `http://192.168.1.9:3000/api/usuarios/actualizar/${usuario.id_usuario}`);
      console.log("📦 CUERPO DEL ENVÍO:", payload);

      // 3. El AWAIT crítico
      const response = await axios.put(
        `http://192.168.1.9:3000/api/usuarios/actualizar/${usuario.id_usuario}`, 
        payload,
        { headers: { 'Content-Type': 'application/json' } }
      );
      
      console.log("✅ RESPUESTA EXITOSA:", response.data);
      Alert.alert("Socio Glaze", "Datos actualizados correctamente.");

    } catch (error) {
      // 4. Captura detallada del Error 400
      console.log("❌ FALLÓ EL AWAIT:");
      if (error.response) {
        console.log("Mensaje del Servidor:", error.response.data);
        Alert.alert("Error 400", error.response.data.error || "Datos inválidos.");
      } else {
        console.log("Error de Red/Conexión:", error.message);
        Alert.alert("Error", "No se pudo contactar al servidor.");
      }
    } finally {
      setLoading(false);
    }
  };

  const actualizarPassword = async () => {
    if (!passwordData.password || !passwordData.password_actual) return Alert.alert("Glaze", "Llene los campos.");
    try {
      setLoading(true);
      await axios.put(`http://192.168.1.9:3000/api/usuarios/password/${usuario.id_usuario}`, passwordData);
      Alert.alert("Seguridad", "Contraseña actualizada.");
      setPasswordData({ password_actual: "", password: "" });
    } catch (error) {
      Alert.alert("Error", "Verifique su contraseña actual.");
    } finally {
      setLoading(false);
    }
  };

  if (cargandoDatos) return <View style={styles.center}><ActivityIndicator color={COLORS.dark} /></View>;

  return (
    <SafeAreaView style={styles.mainWrapper}>
      <StatusBar barStyle="dark-content" />
      <View style={styles.navHeader}>
        <TouchableOpacity onPress={() => router.back()}><Feather name="chevron-left" size={26} color={COLORS.dark} /></TouchableOpacity>
        <Text style={styles.navTitle}>PERFIL PROFESIONAL</Text>
        <View style={{ width: 26 }} />
      </View>

      <KeyboardAvoidingView behavior={Platform.OS === "ios" ? "padding" : "height"} style={{ flex: 1 }}>
        <ScrollView style={styles.container}>
          <View style={styles.headerSection}>
            <Text style={styles.brandTitle}>Ajustes</Text>
            <View style={styles.accentLine} />
          </View>

          <View style={styles.glazeCard}>
            <View style={styles.sideIndicator} />
            <View style={styles.cardPadding}>
              <Text style={styles.sectionLabel}>DATOS PERSONALES</Text>

              <View style={styles.inputBox}>
                <Text style={styles.fieldLabel}>NOMBRE COMPLETO</Text>
                <TextInput style={[styles.input, styles.inputBlocked]} value={usuario.nombre_completo} editable={false} />
              </View>

              <View style={styles.inputBox}>
                <Text style={styles.fieldLabel}>CORREO ELECTRÓNICO</Text>
                <TextInput 
                    style={styles.input} 
                    value={usuario.correo} 
                    onChangeText={(t) => setUsuario({...usuario, correo: t})}
                    autoCapitalize="none"
                />
              </View>

              <View style={styles.inputBox}>
                <Text style={styles.fieldLabel}>CELULAR</Text>
                <TextInput 
                    style={styles.input} 
                    value={usuario.celular} 
                    onChangeText={(t) => setUsuario({...usuario, celular: t})}
                    keyboardType="numeric"
                />
              </View>

              <TouchableOpacity style={styles.btnMain} onPress={guardarCambios} disabled={loading}>
                {loading ? <ActivityIndicator color="white" /> : <Text style={styles.btnMainText}>GUARDAR CAMBIOS</Text>}
              </TouchableOpacity>
            </View>
          </View>

          <View style={styles.glazeCard}>
            <View style={[styles.sideIndicator, {backgroundColor: COLORS.silver}]} />
            <View style={styles.cardPadding}>
              <Text style={styles.sectionLabel}>CAMBIAR CONTRASEÑA</Text>
              <TextInput 
                style={styles.input} 
                placeholder="Contraseña Actual" 
                secureTextEntry 
                value={passwordData.password_actual}
                onChangeText={(t) => setPasswordData({...passwordData, password_actual: t})}
              />
              <TextInput 
                style={[styles.input, {marginTop: 10}]} 
                placeholder="Nueva Contraseña" 
                secureTextEntry 
                value={passwordData.password}
                onChangeText={(t) => setPasswordData({...passwordData, password: t})}
              />
              <TouchableOpacity style={styles.btnSecondary} onPress={actualizarPassword}>
                <Text style={styles.btnSecondaryText}>ACTUALIZAR LLAVE</Text>
              </TouchableOpacity>
            </View>
          </View>
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  mainWrapper: { flex: 1, backgroundColor: COLORS.bg },
  center: { flex: 1, justifyContent: 'center', alignItems: 'center' },
  container: { paddingHorizontal: 20 },
  navHeader: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', padding: 20 },
  navTitle: { fontSize: 10, letterSpacing: 2, fontWeight: '800', color: COLORS.dark },
  headerSection: { marginBottom: 20 },
  brandTitle: { fontSize: 28, fontWeight: '300', color: COLORS.dark },
  accentLine: { width: 30, height: 2, backgroundColor: COLORS.accent, marginVertical: 10 },
  glazeCard: { backgroundColor: COLORS.white, borderRadius: 8, marginBottom: 20, flexDirection: 'row', overflow: 'hidden', elevation: 2 },
  sideIndicator: { width: 4, backgroundColor: COLORS.dark },
  cardPadding: { flex: 1, padding: 20 },
  sectionLabel: { fontSize: 9, fontWeight: "800", color: COLORS.dark, marginBottom: 15 },
  inputBox: { marginBottom: 15 },
